import{_ as o,o as a,c as e,ag as r}from"./chunks/framework.B5ULsuav.js";const d=JSON.parse('{"title":"金刚经4分-无所住行布施","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经4分-无所住行布施.md","filePath":"60-原文段落/金刚经4分-无所住行布施.md","lastUpdated":1778155802000}'),_={name:"60-原文段落/金刚经4分-无所住行布施.md"};function s(u,t,n,p,q,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="金刚经4分-无所住行布施" tabindex="-1">金刚经4分-无所住行布施 <a class="header-anchor" href="#金刚经4分-无所住行布施" aria-label="Permalink to &quot;金刚经4分-无所住行布施&quot;">​</a></h1><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/4了空居士讲《金刚经》-第四分妙行无住分20160916">4了空居士讲《金刚经》-第四分妙行无住分20160916</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>复次，须菩提，菩萨于法，应无所住行于布施</strong></p><p>&quot;复次&quot;就是说：须菩提啊，还有啊，我接下来继续告诉你。&quot;菩萨于法应无所住，行于布施&quot;，&quot;布施&quot;就是没有带着任何想法，自然地去做事情。&quot;菩萨于法，应无所住行于布施&quot;，就是菩萨做一切事情，都不要带着某些私人的不可告人的目的，不要带着任何私心任何目的，应该是大公无私坦坦荡荡地去做该做的事情。这句&quot;于法，应无所住行于布施&quot;就是这个意思。</p><p><strong>所谓不住色布施，不住声、香、味、触、法布施。</strong></p><p>这个就是世尊继续给我们详细的讲解。&quot;所谓&quot;就是说我跟你们说具体一点吧，就是包括&quot;色、声、香、味、触、法&quot;，不要执着这些事情。你不要因为这个人你看着顺眼，你就愿意去帮助他，或者是你这个声音你听起来比较顺耳，所以跟这件事情有关的，你就愿意去帮助他。也就是说你不要有某一些私人的目的，而是还是以客观的实际情况，你很真诚地去帮助，而不是说我顺眼、我这方面我喜欢我才去帮助，不是这个意思。</p><p><strong>须菩提，菩萨应如是布施，不住于相。</strong></p><p>世尊就继续叮咛嘱咐吧，就说：真正的菩萨就一定要这样清清净净的、客客观观地去帮助，去做自己需要做的事情。就是按照客观的状态该怎么做。比如说我们在路上看到有块石头，我就不要看一下周围说&quot;唉呀，看人家有没有看到我在做好事，我就搬石头&quot;，不是！而是很自然流露&quot;唉呀，这个石头在路上，等一下人家不小心会撞到，我就想办法给搬到旁边去&quot;。就是说，不要有条件的去做，而是无条件的，是一种自然的流露。</p>',9)])])}const l=o(_,[["render",s]]);export{d as __pageData,l as default};
